func TestLocalCommandArgumentsAreNotTheOwners(t *testing.T) {
	lines := Lines(strings.NewReader(strings.Join(slashCommands, "\n")+"\n"), Claude, true)
	var own []string
	for _, l := range lines {
		if strings.HasPrefix(l, "U: ") {
			own = append(own, l)
		}
	}
	if len(own) != 2 || own[0] != "U: finish the parser fixes and keep the tests green, dont stop to ask" || own[1] != "U: redo the the UI" {
		t.Fatalf("owner lines %q\nall:\n%s", own, strings.Join(lines, "\n"))
	}
	all := strings.Join(lines, "\n")
	if !strings.Contains(all, "H: <command-name>/effort") || !strings.Contains(all, "H: <command-name>/auto-mode-setup") || !strings.Contains(all, "H: Base directory for this skill") {
		t.Fatalf("the local commands are not the harness's:\n%s", all)
	}

	// Line by line, as the corpus and the reviewer read.
	var c ClaudeCommands
	var local []bool
	for _, l := range slashCommands {
		local = append(local, c.LocalLine([]byte(l)))
	}
	want := []bool{false, true, false, false, true, false, false, false, false, false, false, false}
	for i := range want {
		if local[i] != want[i] {
			t.Fatalf("local %v, want %v", local, want)
		}
	}
	// An echo with its caveat in the same text.
	if ps := OwnerPieces(TurnPieces("<local-command-caveat>Caveat: run locally</local-command-caveat>\n<command-name>/model</command-name>\n<command-args>claude-opus-5-5</command-args>")); len(ps) != 0 {
		t.Fatalf("pieces %q", ps)
	}
}
